import { chromium, Page } from '@playwright/test';

export interface TestResult {
  name: string;
  status: 'passed' | 'failed' | 'skipped';
  vulnType: string;
  severity: 'low' | 'medium' | 'high' | 'critical';
  description: string;
  evidence: string;
  stepsToReproduce: string[];
}

export interface TestContext {
  page: Page;
  baseURL: string;
  token?: string;
}

export class VulnerabilityRunner {
  private context: TestContext;
  private page: Page;

  constructor(context: TestContext) {
    this.context = context;
  }

  async runTest(
    testName: string,
    vulnType: string,
    severity: 'low' | 'medium' | 'high' | 'critical',
    description: string,
    testFn: (page: Page) => Promise<string> // returns evidence
  ): Promise<TestResult> {
    try {
      const context = await this.context.page.evaluate(page => {
        return page.evaluate(() => {
          console.log('Runner active', window.location.href);
          return 'OK';
        });
      });

      const evidence = await testFn(this.context.page);

      if (evidence.trim().length > 0) {
        return {
          name: testName,
          status: 'failed' as const,
          vulnType,
          severity,
          description,
          evidence,
          stepsToReproduce: [],
        };
      }

      return {
        name: testName,
        status: 'passed' as const,
        vulnType,
        severity,
        description,
        evidence: '',
        stepsToReproduce: [],
      };
    } catch (error) {
      return {
        name: testName,
        status: 'failed' as const,
        vulnType,
        severity,
        description,
        evidence: String(error),
        stepsToReproduce: [],
      };
    }
  }

  async runAllTests(
    tests: Array<{ testName: string; testFn: (page: Page) => Promise<string> }>
  ): Promise<TestResult[]> {
    const results: TestResult[] = [];
    for (const test of tests) {
      const result = await this.runTest(
        test.testName,
        'N/A',
        'low',
        '',
        test.testFn
      );
      results.push(result);
    }
    return results;
  }
}

export interface PolicyRule {
  id: string;
  name: string;
  description: string;
  category: 'owasp-top10' | 'custom';
  severity: 'low' | 'medium' | 'high' | 'critical';
  conditions: Array<{
    field: string;
    operator: 'contains' | 'startsWith' | 'endsWith' | 'regex' | 'equals';
    value: string;
  }>;
  actions: Array<{
    type: 'checkVulnerability' | 'checkAuth' | 'checkData';
    vulnRunner: string; // class name from vuln/ folder
  }>;
  priority: number;
}

export interface MatchResult {
  ruleId: string;
  ruleName: string;
  matchedConditions: Array<string>;
  matchedAt: Date;
}

export type MatchCallback = (result: MatchResult) => void;

export class PolicyEngine {
  private rules: PolicyRule[];
  private callbacks: Array<MatchCallback>;

  constructor() {
    this.rules = [];
    this.callbacks = [];
  }

  registerRule(rule: PolicyRule): void {
    this.rules.push(rule);
  }

  registerCallback(callback: MatchCallback): void {
    this.callbacks.push(callback);
  }

  private async checkConditions(
    rule: PolicyRule,
    page: any
  ): Promise<MatchResult | null> {
    const matched = new Array<string>();

    for (const cond of rule.conditions) {
      let evalResult: string;
      switch (cond.operator) {
        case 'contains':
          evalResult = await page.evaluate(cond.value);
          if (evalResult.includes(cond.value)) {
            matched.push(`Contains "${cond.value}"`);
          }
          break;
        case 'startsWith':
          evalResult = await page.evaluate(cond.value);
          if (evalResult.startsWith(cond.value)) {
            matched.push(`Starts with "${cond.value}"`);
          }
          break;
        case 'endsWith':
          evalResult = await page.evaluate(cond.value);
          if (evalResult.endsWith(cond.value)) {
            matched.push(`Ends with "${cond.value}"`);
          }
          break;
        case 'regex': {
          const pattern = new RegExp(cond.value);
          const evalResult = await page.evaluate(cond.value);
          if (pattern.test(evalResult)) {
            matched.push(`Matches regex /${cond.value}/`);
          }
          break;
        }
        case 'equals':
          evalResult = await page.evaluate(cond.value);
          if (evalResult === cond.value) {
            matched.push(`Equals "${cond.value}"`);
          }
          break;
        default:
          throw new Error(`Unknown operator: ${cond.operator}`);
      }
    }

    return matched.length > 0 ? {
      ruleId: rule.id,
      ruleName: rule.name,
      matchedConditions,
      matchedAt: new Date(),
    } : null;
  }

  async match(page: any): Promise<MatchResult[]> {
    const results: MatchResult[] = [];

    for (const rule of this.rules) {
      const match = await this.checkConditions(rule, page);
      if (match) {
        for (const callback of this.callbacks) {
          callback(match);
        }
        results.push(match);
      }
    }

    return results;
  }
}

import { Page } from '@playwright/test';

export interface PipelineStage {
  name: string;
  description: string;
  testFn: (page: Page, url: string) => Promise<string>;
}

export type TestFn = (page: Page, url: string) => Promise<string>;

export class PentestPipeline {
  private stages: PipelineStage[];
  private callbacks: Array<(stage: PipelineStage, stageResult: string) => void>;

  constructor() {
    this.stages = [];
    this.callbacks = [];
  }

  addStage(stage: PipelineStage): void {
    this.stages.push(stage);
  }

  registerCallback(callback: (stage: PipelineStage, stageResult: string) => void): void {
    this.callbacks.push(callback);
  }

  private async executeStage(
    stage: PipelineStage,
    page: Page,
    url: string
  ): Promise<string> {
    const result = await stage.testFn(page, url);
    for (const callback of this.callbacks) {
      callback(stage, result);
    }
    return result;
  }

  async run(
    page: Page,
    url: string
  ): Promise<Array<{ stageName: string; stageResult: string }> > {
    const results = [];

    for (const stage of this.stages) {
      try {
        const result = await this.executeStage(stage, page, url);
        results.push({
          stageName: stage.name,
          stageResult,
        });
      } catch (error) {
        results.push({
          stageName: stage.name,
          stageResult: `Error: ${String(error)}`,
        });
      }
    }

    return results;
  }
}

export interface ScanResult {
  scanId: string;
  startTime: Date;
  endTime: Date;
  targetUrl: string;
  results: Array<{
    vulnType: string;
    severity: 'low' | 'medium' | 'high' | 'critical';
    description: string;
    status: 'passed' | 'failed';
    evidence: string;
    stepsToReproduce: string[];
  }>;
  summary: {
    totalVulnerabilities: number;
    bySeverity: Array<{ severity: string; count: number }>;
  };
}

export class ReportGenerator {
  private results: ScanResult[];

  constructor() {
    this.results = [];
  }

  addResult(result: ScanResult): void {
    this.results.push(result);
  }

  generateJSON(): string {
    return JSON.stringify(
      {
        scanResults: this.results.map((r) => ({
          scanId: r.scanId,
          startTime: r.startTime.toISOString(),
          endTime: r.endTime.toISOString(),
          targetUrl: r.targetUrl,
          results: r.results.map((res) => ({
            vulnType: res.vulnType,
            severity: res.severity,
            description: res.description,
            status: res.status,
            evidence: res.evidence,
            stepsToReproduce: res.stepsToReproduce,
          })),
          summary: r.summary,
        })),
      },
      null,
      2
    );
  }

  generateHTML(): string {
    const summary = this.results
      .reduce(
        (acc, res) => {
          for (const vuln of res.results) {
            acc[vuln.severity]++;
          }
          return acc;
        },
        { low: 0, medium: 0, high: 0, critical: 0 }
      )
      .toString();

    let html = `<html><head><style>`;
    html += `
  body { font-family: sans-serif; }
  h1 { color: #333; }
  table {
    border-collapse: collapse; width: 100%; margin-top: 20px;
  }
  th, td {
    border: 1px solid #ddd; padding: 12px; text-align: left;
  }
  th { background-color: #f5f5f5; }
  .critical { color: #d32f2f; font-weight: bold; }
  .high { color: #f57c00; font-weight: bold; }
  .medium { color: #1976d2; }
  .low { color: #4caf50; }
  summary { cursor: pointer; user-select: none; }
`;
    html += `</style></head><body><h1>OWASP TOP 10 Penetration Test Report</h1>`;
    html += `<p>Generated at ${new Date().toISOString()}</p>`;
    html += `<p>Summary — Critical: ${summary.critical}, High: ${summary.high}, Medium: ${summary.medium}, Low: ${summary.low}</p>`;

    let tableRows = '<table><tr><th>Scan ID</th><th>Target URL</th><th>Status</th></tr>';
    for (const result of this.results) {
      const status = result.results.find((r) => r.status === 'failed')
        ? 'Failed'
        : 'Passed';
      tableRows += `<tr><td>${result.scanId}</td>`;
      tableRows += `<td>${result.targetUrl}</td>`;
      tableRows += `<td>${status}</td></tr>`;
    }
    tableRows += '</table>';

    html += tableRows;
    html += '</body></html>';
    return html;
  }

  generateMarkdown(): string {
    let md = '# OWASP TOP 10 Penetration Test Report\n';
    md += `Generated at ${new Date().toISOString()}\n\n`;

    for (const result of this.results) {
      md += `## Scan: ${result.scanId}\n`;
      md += `- **Target URL**: ${result.targetUrl}\n`;
      md += `- **Status**: ${result.results.find((r) => r.status === 'failed') ? 'Failed' : 'Passed'}\n`;
      md += '- **Vulnerabilities Found**: `' +
        result.results.filter((r) => r.status === 'failed').length +
        `\n`;
      md += '\n### Results:\n';

      for (const vuln of result.results) {
        md += `- [${vuln.severity}] ${vuln.description}\n`;
        md += `  *Evidence*: ${vuln.evidence}\n\n`;
      }
    }

    return md;
  }
}

import { VulnerabilityRunner, TestResult } from '../../core/runner';

export interface VulnTest {
  name: string;
  testFn: (page: any, url: string) => Promise<string>;
}

export class TestCases {
  private runner: VulnerabilityRunner;
  private url: string;
  private tests: VulnTest[] = [];

  constructor(runner: VulnerabilityRunner, url: string) {
    this.runner = runner;
    this.url = url;
  }

  addTest(test: VulnTest): void {
    this.tests.push(test);
  }

  async runAll(): Promise<TestResult[]> {
    const results: TestResult[] = [];
    for (const test of this.tests) {
      const result = await this.runner.runTest(
        test.name,
        '',
        'low',
        '',
        test.testFn
      );
      results.push(result);
    }
    return results;
  }
}

#!/usr/bin/env node
import { parse } from 'yaml';
import fs from 'fs/promises';
import path from 'path';

const configDir = path.join(__dirname, '..', 'config');

export async function main(): Promise<void> {
  const args = process.argv.slice(2);
  const command = args[0] ?? 'help';

  switch (command) {
    case 'init': {
      // Initialize project with config files
      console.log('[INIT] Creating test suite configuration...');
      await initConfig();
      break;
    }

    case 'scan': {
      const targetUrl = args[1];
      if (!targetUrl) {
        console.error('[ERROR] Missing target URL: web-app-pentest scan <url>');
        process.exit(1);
      }
      await scanTarget(targetUrl);
      break;
    }

    case 'generate-report': {
      const outputPath = args[1];
      if (!outputPath) {
        console.error('[ERROR] Missing output path: web-app-pentest generate-report <path>');
        process.exit(1);
      }
      await generateReport(outputPath);
      break;
    }

    case 'help':
    default:
      printHelp();
      break;
  }
}

async function initConfig(): Promise<void> {
  // Initialize config files if they don't exist
  const testSuitePath = path.join(configDir, 'test-suite.yaml');
  const targetsPath = path.join(configDir, 'targets.yaml');

  if (!fs.existsSync(testSuitePath)) {
    await fs.writeFile(
      testSuitePath,
      '# OWASP TOP 10 Penetration Test Suite Configuration\n# See config/test-suite.yaml.example for template'
    );
    console.log(`  - Created ${testSuitePath}`);
  }

  if (!fs.existsSync(targetsPath)) {
    await fs.writeFile(
      targetsPath,
      '# Targets configuration — see config/targets.yaml.example\n# Define app URLs and endpoints to test'
    );
    console.log(`  - Created ${targetsPath}`);
  }
}

async function scanTarget(targetUrl: string): Promise<void> {
  console.log('[SCAN] Starting penetration test on:', targetUrl);
  // Implementation goes here
  console.log(`[SCAN] Target URL: ${targetUrl}`);
}

async function generateReport(outputPath: string): Promise<void> {
  const outputDir = path.dirname(outputPath);
  await fs.mkdir(outputDir, { recursive: true });

  console.log('[REPORT] Generating report to:', outputPath);
  // Implementation goes here
  console.log(`[REPORT] Output path: ${outputPath}`);
}

function printHelp(): void {
  console.log(`
web-app-pentest — OWASP TOP 10 Penetration Test Suite

Commands:
  init           Initialize project with default configuration
  scan <url>     Run penetration test on target URL
  generate-report <path>  Generate reports from scan results

Examples:
  $ web-app-pentest init
  $ web-app-pentest scan https://example-app.local
  $ web-app-pentest generate-report results.html
`);
}

