import { Page } from '@playwright/test';
import chalk from 'chalk';

export interface ReconResult {
  url: string;
  title: string;
  metaTags: Array<{ name: string; content?: string }>;
  favicon: boolean;
  techStackDetected: string[];
  endpoints: Array<{ path: string; method: 'GET' | 'POST' }>; 
}

export async function scanRecon(page: Page, url: string): Promise<ReconResult> {
  const result: ReconResult = {
    url,
    title: '',
    metaTags: [],
    favicon: false,
    techStackDetected: [],
    endpoints: [],
  };

  await page.goto(url, { waitUntil: 'networkidle' });

  result.title = await page.title();

  result.metaTags.push({
    name: 'viewport',
    content: await page.locator('meta[name="viewport"]').getAttribute('content'),
  });
  result.metaTags.push({
    name: 'description',
    content: await page.locator('meta[name="description"]').getAttribute('content'),
  });

  result.favicon = await page.locator('link[rel="icon"], link[rel="shortcut icon"]').count() > 0;

  const js = await page.evaluate(() => {
    const scripts = Array.from(document.scripts);
    return scripts.map((script) => script.src).filter(Boolean);
  });

  result.techStackDetected.push('JavaScript framework detected from JS files');

  const html = await page.content();
  if (html.includes('react') || html.includes('React')) {
    result.techStackDetected.push('React');
  }
  if (html.includes('vue') || html.includes('Vue')) {
    result.techStackDetected.push('Vue.js');
  }

  await page.route('**/*', async (route) => {
    const response = await route.fetch();
    const contentType = response.headers().get('Content-Type') ?? '';
    if (/\bjson\b/i.test(contentType)) {
      const apiPath = new URL(response.url()).pathname.replace(/^\/api\//, '');
      result.endpoints.push({ path: `/${apiPath}`, method: 'GET' });
    }
  });

  return result;
}

export async function reconRun(url: string): Promise<ReconResult> {
  const browser = await chromium.launch();
  const context = await browser.newContext();
  const page = await context.newPage();
  page.setDefaultTimeout(30_000);
  const result = await scanRecon(page, url);
  await browser.close();
  return result;
}

import { Page } from '@playwright/test';
import chalk from 'chalk';

export interface SQLiResult {
  vulnType: 'A01-SQLi';
  severity: 'critical';
  description: string;
  status: 'passed' | 'failed';
  evidence: string;
  stepsToReproduce: Array<string>;
}

const sqliKeywords = ["UNION", "SELECT", "DROP", "INSERT", "UPDATE"];
const sqliPayloads = [
  "' UNION SELECT 1,2,3--",
  "'");
];

export async function testSQLi(page: Page, url: string): Promise<SQLiResult> {
  const result: SQLiResult = {
    vulnType: 'A01-SQLi',
    severity: 'critical',
    description: 'Detect SQL injection vulnerabilities in search and form parameters',
    status: 'passed',
    evidence: '',
    stepsToReproduce: [],
  };

  try {
    await page.goto(url, { waitUntil: 'networkidle' });

    const inputField = await page.locator('input[type="search"], input[name="q"]');
    if (inputField.count() > 0) {
      const payload = "' UNION SELECT SLEEP(3)-- ";
      await inputField.fill(payload);
      await inputField.press('Enter');
      const body = await page.content();
      for (const keyword of sqliKeywords) {
        if (body.includes(keyword)) {
          result.status = 'failed';
          result.evidence = `Keyword '${keyword}' found in page response, indicating SQL injection possible via input parameter`;
          result.stepsToReproduce.push(`1. Navigate to ${url}`);
          result.stepsToReproduce.push(`2. Enter payload "' UNION SELECT SLEEP(3)-- " into search box`);
          result.stepsToReproduce.push(`3. Submit form — observe database error containing keyword '${keyword}'`);
          return result;
        }
      }
    }

    return result;
  } catch (error) {
    result.evidence = String(error);
    return result;
  }
}

import { Page } from '@playwright/test';
import chalk from 'chalk';

export interface XSSResult {
  vulnType: 'A04-XSS';
  severity: 'critical';
  description: string;
  status: 'passed' | 'failed';
  evidence: string;
  stepsToReproduce: Array<string>;
}

const xssPayloads = [
  "<script>alert('XSS')</script>",
  "javascript:alert('XSS')",
];

export async function testReflectedXSS(page: Page, url: string): Promise<XSSResult> {
  const result: XSSResult = {
    vulnType: 'A04-XSS',
    severity: 'critical',
    description: 'Detect reflected XSS in search and GET parameters',
    status: 'passed',
    evidence: '',
    stepsToReproduce: [],
  };

  try {
    await page.goto(url, { waitUntil: 'networkidle' });

    const inputField = await page.locator('input[type="search"], input[name="q"]');
    if (inputField.count() > 0) {
      const payload = "<script>alert('XSS')</script>";
      await inputField.fill(payload);
      await inputField.press('Enter');
      const body = await page.content();

      for (const payload of xssPayloads) {
        if (body.includes(payload)) {
          result.status = 'failed';
          result.evidence = `XSS payload '${payload}' echoed in page response — reflected XSS confirmed`;
          result.stepsToReproduce.push(`1. Navigate to ${url}`);
          result.stepsToReproduce.push(`2. Enter payload "<script>alert('XSS')</script>" into search box`);
          result.stepsToReproduce.push(`3. Submit form — observe XSS payload echoed in DOM`);
          return result;
        }
      }

