import { chromium } from '@playwright/test';
import { PentestPipeline } from './pipeline';

export interface OrchestratorResult {
  scanId: string;
  targetUrl: string;
  startTime: Date;
  endTime: Date;
  results: Array<{
    stageName: string;
    stageResult: string;
    vulnType: string;
    severity: 'low' | 'medium' | 'high' | 'critical';
    status: 'passed' | 'failed';
    evidence: string;
    remediationAdvice: Array<string>;
  }>;
  summary: {
    totalVulnerabilities: number;
    critical: number;
    high: number;
    medium: number;
    low: number;
  };
}

export async function orchestrate(url: string): Promise<OrchestratorResult> {
  const scanId = Date.now().toString();
  const startTime = new Date();

  const browser = await chromium.launch();
  const context = await browser.newContext();
  const page = await context.newPage();
  page.setDefaultTimeout(30_000);

  const pipeline = new PentestPipeline();

  pipeline.addStage({
    name: 'Recon',
    description: 'Reconnaissance and discovery phase',
    testFn: async () => {
      return `Recon stage completed — gathered title, meta tags, endpoints`;
    },
  });

  pipeline.addStage({
    name: 'Vuln Scan',
    description: 'OWASP TOP 10 vulnerability scanning',
    testFn: async () => {
      return `Vulnerability scan initiated — testing A01–A10`;
    },
  });

  const results = [];
  for (const stage of pipeline.stages) {
    try {
      const result = await pipeline.executeStage(stage, page, url);
      results.push({
        stageName: stage.name,
        stageResult,
        vulnType: '',
        severity: 'low',
        status: 'passed',
        evidence: '',
        remediationAdvice: [],
      });
    } catch (error) {
      results.push({
        stageName: stage.name,
        stageResult: `Error: ${String(error)}`,
        vulnType: '',
        severity: 'low',
        status: 'failed',
        evidence: String(error),
        remediationAdvice: [],
      });
    }
  }

  const endTime = new Date();

  await browser.close();

  return {
    scanId,
    targetUrl: url,
    startTime,
    endTime,
    results,
    summary: {
      totalVulnerabilities: 0,
      critical: 0,
      high: 0,
      medium: 0,
      low: 0,
    },
  };
}

