// pipeline.test.js
import { describe, it } from 'node:test';
import assert from 'assert';

import { PentestPipeline } from '../src/core/pipeline.js';

// ── Tests for Pipeline Stage Execution ────────────────────────

describe('PentestPipeline', () => {
  describe('#constructor', () => {
    it('initializes with empty stages array and zero callbacks', () => {
      const pipeline = new PentestPipeline();
      assert.strictEqual(pipeline.stages.length, 0);
      assert.strictEqual(pipeline.callbacks.length, 0);
    });
  });

  describe('#addStage', () => {
    it('adds a stage to the internal array', () => {
      const pipeline = new PentestPipeline();
      pipeline.addStage({ name: 'Recon', testFn: async () => 'OK' });
      assert.strictEqual(pipeline.stages.length, 1);
      assert.strictEqual(pipeline.stages[0].name, 'Recon');
    });

    it('preserves added stage metadata (description, testFn)', () => {
      const pipeline = new PentestPipeline();
      pipeline.addStage({
        name: 'Vuln',
        description: 'OWASP TOP 10 scan',
        testFn: async () => 'OK',
      });
      assert.strictEqual(pipeline.stages[0].description, 'OWASP TOP 10 scan');
      assert.strictEqual(typeof pipeline.stages[0].testFn, 'function');
    });
  });

  describe('#registerCallback', () => {
    it('registers a callback for stage results', async () => {
      const pipeline = new PentestPipeline();
      let fired = false;
      pipeline.registerCallback((stage, result) => {
        assert.strictEqual(stage.name, 'Recon');
        assert.strictEqual(result, 'OK');
        fired = true;
      });

      await pipeline.run(null, 'https://example.com');
      assert.strictEqual(fired, true);
    });

    it('accumulates multiple callbacks without error', async () => {
      const pipeline = new PentestPipeline();
      let count = 0;
      pipeline.registerCallback(() => { count++; });
      pipeline.registerCallback(() => { count++; });
      await pipeline.run(null, 'https://example.com');
      assert.strictEqual(count, 2);
    });
  });

  describe('#run', () => {
    it('executes all stages sequentially and returns results array', async () => {
      const pipeline = new PentestPipeline();
      pipeline.addStage({ name: 'S1', testFn: async () => 'OK' });
      pipeline.addStage({ name: 'S2', testFn: async () => 'OK' });

      const results = await pipeline.run(null, 'https://example.com');
      assert.strictEqual(results.length, 2);
      assert.deepStrictEqual(results[0], {
        stageName: 'S1',
        stageResult: 'OK',
      });
      assert.deepStrictEqual(results[1], {
        stageName: 'S2',
        stageResult: 'OK',
      });
    });

    it('catches errors from failing stages and returns error object', async () => {
      const pipeline = new PentestPipeline();
      pipeline.addStage({ name: 'FailMe', testFn: async () => { throw new Error('boom'); }});

      const results = await pipeline.run(null, 'https://example.com');
      assert.strictEqual(results.length, 1);
      assert.strictEqual(results[0].stageResult.startsWith('Error:'), true);
    });

    it('handles synchronous failures without crashing', async () => {
      const pipeline = new PentestPipeline();
      pipeline.addStage({ name: 'SyncFail', testFn: () => 'OK' });

      await assert.doesNotThrow(() => pipeline.run(null, 'https://example.com'));
    });
  });
});

// recon.test.js
import { describe, it } from 'node:test';
import assert from 'assert';

// ── Tests for Reconnaissance ──────────────────────────────────────────────

describe('Recon Stage', () => {
  // These tests validate the Playwright reconnaissance module
  it('detects page title and meta tags via Playwright', async () => {
    const browser = await globalThis.playwright?.launch();
    if (!browser) { return; }
    const context = await browser.newContext();
    const page = await context.newPage();
    await page.goto('https://example.com');
    assert.strictEqual(page.title(), 'Example Domain');
  });

  it('extracts viewport and description meta tags from page', async () => {
    const browser = await globalThis.playwright?.launch();
    if (!browser) { return; }
    const context = await browser.newContext();
    const page = await context.newPage();
    await page.goto('https://example.com');
    const viewport = await page.locator('meta[name="viewport"]').getAttribute('content');
    assert.ok(viewport?.includes('width=device-width'), 'viewport detected');
  });

  it('detects favicon presence via link rel=icon', async () => {
    const browser = await globalThis.playwright?.launch();
    if (!browser) { return; }
    const context = await browser.newContext();
    const page = await context.newPage();
    await page.goto('https://example.com');
    const count = await page.locator('link[rel="icon"], link[rel="shortcut icon"]').count();
    assert.ok(count >= 0, 'favicon check returns valid count');
  });

  it('extracts JavaScript file sources to detect React/Vue', async () => {
    const browser = await globalThis.playwright?.launch();
    if (!browser) { return; }
    const context = await browser.newContext();
    const page = await context.newPage();
    await page.goto('https://reactjs.org');
    const scripts = await page.evaluate(() => {
      return Array.from(document.scripts)
        .map(s => s.src)
        .filter(Boolean);
    });
    assert.ok(Array.isArray(scripts), 'scripts extracted as array');
  });

  it('intercepts API routes to discover endpoints', async () => {
    const browser = await globalThis.playwright?.launch();
    if (!browser) { return; }
    const context = await browser.newContext();
    const page = await context.newPage();
    await page.goto('https://jsonplaceholder.typicode.com');
    const response = await page.route('**/*', async route => {
      const contentType = route.request().headers()['content-type'] ?? '';
      if (/\bjson\b/i.test(contentType)) {
        await route.continue();
      } else {
        await route.fulfill({});
      }
    });
  });
});

// vuln.test.js
import { describe, it } from 'node:test';
import assert from 'assert';

// ── Tests for Vulnerability Scanning (OWASP TOP 10) ──────────────────────

describe('Vulnerability Scanner', () => {
  // SQLi Test Cases
  it('SQLi test returns passed status when no injection detected', async () => {
    const sqlResult = await sqlitest();
    assert.strictEqual(sqlResult.status, 'passed');
    assert.strictEqual(sqlResult.vulnType, 'A01-SQLi');
  });

  it('SQLi test returns critical severity consistently', async () => {
    const sqlResult = await sqlitest();
    assert.strictEqual(sqlResult.severity, 'critical');
  });

  // XSS Test Cases
  it('XSS test returns passed status when no injection detected', async () => {
    const xssResult = await xssTest();
    assert.strictEqual(xssResult.status, 'passed');
    assert.strictEqual(xssResult.vulnType, 'A04-XSS');
  });

  it('XSS test returns critical severity consistently', async () => {
    const xssResult = await xssTest();
    assert.strictEqual(xssResult.severity, 'critical');
  });

  // Broken Auth Test Cases
  it('BrokenAuth test returns passed status when no hijacking detected', async () => {
    const authResult = await authTest();
    assert.strictEqual(authResult.status, 'passed');
    assert.strictEqual(authResult.vulnType, 'A02-Broken-Auth');
  });

  it('BrokenAuth test returns high severity consistently', async () => {
    const authResult = await authTest();
    assert.strictEqual(authResult.severity, 'high');
  });

  // Broken Access Test Cases
  it('BrokenAccess test returns passed status when no IDOR detected', async () => {
    const accessResult = await accessTest();
    assert.strictEqual(accessResult.status, 'passed');
    assert.strictEqual(accessResult.vulnType, 'A05-Broken-Access');
  });

  it('BrokenAccess test returns critical severity consistently', async () => {
    const accessResult = await accessTest();
    assert.strictEqual(accessResult.severity, 'critical');
  });
});

// orchestrator.test.js
import { describe, it } from 'node:test';
import assert from 'assert';

// ── Tests for Orchestrator Stage Coordination ──────────────────────────────

describe('Orchestrator', () => {
  // Verify that the orchestrator correctly chains all stages together
  it('orchestrates all stages in order without skipping or duplicates', async () => {
    const browser = await globalThis.playwright?.launch();
    if (!browser) { return; }
    const context = await browser.newContext();
    const page = await context.newPage();
    await page.goto('https://example.com');
    // Verify all stages execute sequentially
  });

  it('handles stage failures without crashing the orchestrator', async () => {
    const browser = await globalThis.playwright?.launch();
    if (!browser) { return; }
    const context = await browser.newContext();
    const page = await context.newPage();
    // Test that stage errors are caught and reported correctly
  });

  it('tracks total vulnerabilities across all stages', async () => {
    const browser = await globalThis.playwright?.launch();
    if (!browser) { return; }
    const context = await browser.newContext();
    const page = await context.newPage();
    // Verify that vulnerability counts are aggregated correctly
  });

  it('aggregates findings by severity (critical, high, medium, low)', async () => {
    const browser = await globalThis.playwright?.launch();
    if (!browser) { return; }
    const context = await browser.newContext();
    const page = await context.newPage();
    // Verify that severity aggregation works correctly
  });
});

// report.test.js
import { describe, it } from 'node:test';
import assert from 'assert';

// ── Tests for Report Generation (HTML/Markdown/JSON) ──────────────────────

describe('Report Generator', () => {
  // Verify that reports are generated correctly in HTML, Markdown, and JSON formats
  it('generates HTML report with correct vulnerability counts by severity', async () => {
    const htmlOutput = await generateHTML();
    assert.ok(htmlOutput.includes('OWASP TOP 10 Penetration Test Report'), 'HTML report header present');
