});

// test/index.js — Main Test Runner
import { run, describe } from 'node:test';
import assert from 'assert';
import fs from 'fs';
import path from 'path';

// ── Global Playwright initialization for shared browser context ─────────────────
globalThis.playwright = null;

before(async () => {
  playwright = await globalThis.playwright?.launch();
});

after(async () => {
  if (globalThis.playwright) {
    await globalThis.playwright?.close();
  }
});

// ── Test Discovery: Read All Test Files From /test —──────────────────────────────

const testFiles = [];
const testDir = path.resolve('./test');

fs.readdirSync(testDir, { withFileTypes: true })
  .filter(d => d.isFile() && d.name.endsWith('.test.js'))
  .forEach(f => testFiles.push(path.join(testDir, f.name)));

console.log('Discovering tests in', testDir);
console.log(testFiles.length, 'tests found');

// ── Run Each Test Module ─────────────────────────────────────────────────────────

for (const filePath of testFiles) {
  try {
    const modulePath = path.resolve(filePath);
    await run(modulePath, { timeout: 10_000 });
    console.log('✅', modulePath, 'passed');
  } catch (error) {
    console.error('❌', modulePath, 'failed:', error.message);
  }
}

