}

import { Page } from '@playwright/test';

export interface PipelineStage {
  name: string;
  description: string;
  testFn: (page: Page, url: string) => Promise<string>;
}

export type TestFn = (page: Page, url: string) => Promise<string>;

export class PentestPipeline {
  private stages: PipelineStage[] = [];
  private callbacks = new Array<(stage: PipelineStage, stageResult: string) => void>();

  addStage(stage: PipelineStage): void {
    this.stages.push(stage);
  }

  registerCallback(callback: (stage: PipelineStage, stageResult: string) => void): void {
    this.callbacks.push(callback);
  }

  private async executeStage(
    stage: PipelineStage,
    page: Page,
    url: string
  ): Promise<string> {
    const result = await stage.testFn(page, url);
    for (const callback of this.callbacks) {
      callback(stage, result);
    }
    return result;
  }

  async run(
    page: Page,
    url: string
  ): Promise<Array<{ stageName: string; stageResult: string }> > {
    const results = [];
    for (const stage of this.stages) {
      try {
        const result = await this.executeStage(stage, page, url);
        results.push({ stageName: stage.name, stageResult });
      } catch (error) {
        results.push({
          stageName: stage.name,
          stageResult: `Error: ${String(error)}`,
        });
      }
    }
    return results;
  }
}

import { Page } from '@playwright/test';
import chalk from 'chalk';

export interface ReconResult {
  url: string;
  title: string;
  metaTags: Array<{ name: string; content?: string }>;
  favicon: boolean;
  techStackDetected: string[];
  endpoints: Array<{ path: string; method: 'GET' | 'POST' }>;
}

export async function scanRecon(page: Page, url: string): Promise<ReconResult> {
  const result: ReconResult = {
    url,
    title: '',
    metaTags: [],
    favicon: false,
    techStackDetected: [],
    endpoints: [],
  };

  await page.goto(url, { waitUntil: 'networkidle' });

  result.title = await page.title();

  result.metaTags.push({
    name: 'viewport',
    content: await page.locator('meta[name="viewport"]').getAttribute('content'),
  });
  result.metaTags.push({
    name: 'description',
    content: await page.locator('meta[name="description"]').getAttribute('content'),
  });

  result.favicon = await page.locator('link[rel="icon"], link[rel="shortcut icon"]').count() > 0;

  const js = await page.evaluate(() => {
    const scripts = Array.from(document.scripts);
    return scripts.map((script) => script.src).filter(Boolean);
  });

  result.techStackDetected.push('JavaScript framework detected from JS files');
  if (js.some(s => s.includes('react'))) {
    result.techStackDetected.push('React');
  }
  if (js.some(s => s.includes('vue'))) {
    result.techStackDetected.push('Vue.js');
  }

  const html = await page.content();
  if (html.includes('/api')) {
    result.endpoints.push({ path: '/api', method: 'GET' });
  }

  return result;
}

export async function reconRun(url: string): Promise<ReconResult> {
  const browser = await chromium.launch();
  const context = await browser.newContext();
  const page = await context.newPage();
  page.setDefaultTimeout(30_000);
  const result = await scanRecon(page, url);
  await browser.close();
  return result;
}

import { chromium } from '@playwright/test';
import { PentestPipeline } from './pipeline';

export interface OrchestratorResult {
  scanId: string;
  targetUrl: string;
  startTime: Date;
  endTime: Date;
  results: Array<{
    stageName: string;
    stageResult: string;
    vulnType: string;
    severity: 'low' | 'medium' | 'high' | 'critical';
    status: 'passed' | 'failed';
    evidence: string;
    remediationAdvice: Array<string>;
  }>;
  summary: {
    totalVulnerabilities: number;
    critical: number;
    high: number;
    medium: number;
    low: number;
  };
}

export async function orchestrate(url: string): Promise<OrchestratorResult> {
  const scanId = Date.now().toString();
  const startTime = new Date();

  const browser = await chromium.launch();
  const context = await browser.newContext();
  const page = await context.newPage();
  page.setDefaultTimeout(30_000);

  const pipeline = new PentestPipeline();

  pipeline.addStage({
    name: 'Recon',
    description: 'Reconnaissance and discovery phase',
    testFn: async () => {
      return `Recon stage completed — gathered title, meta tags, endpoints`;
    },
  });

  pipeline.addStage({
    name: 'Vuln Scan',
    description: 'OWASP TOP 10 vulnerability scanning',
    testFn: async () => {
      return `Vulnerability scan initiated — testing A01–A10`;
    },
  });

  const results = [];
  for (const stage of pipeline.stages) {
    try {
      const result = await pipeline.executeStage(stage, page, url);
      results.push({
        stageName: stage.name,
        stageResult,
        vulnType: '',
        severity: 'low',
        status: 'passed',
        evidence: '',
        remediationAdvice: [],
      });
    } catch (error) {
      results.push({
        stageName: stage.name,
        stageResult: `Error: ${String(error)}`,
        vulnType: '',
        severity: 'low',
        status: 'failed',
        evidence: String(error),
        remediationAdvice: [],
      });
    }
  }

  const endTime = new Date();

  await browser.close();

  return {
    scanId,
    targetUrl: url,
    startTime,
    endTime,
    results,
    summary: {
      totalVulnerabilities: 0,
      critical: 0,
      high: 0,
      medium: 0,
      low: 0,
    },
  };
}

import { Page } from '@playwright/test';
import chalk from 'chalk';

export interface SQLiResult {
  vulnType: 'A01-SQLi';
