const sqliKeywords = ["UNION", "SELECT", "DROP", "INSERT", "UPDATE"];

export async function testSQLi(page: Page, url: string): Promise<SQLiResult> {
  const result: SQLiResult = {
    vulnType: 'A01-SQLi',
    severity: 'critical',
    description: 'Detect SQL injection vulnerabilities in search and form parameters',
    status: 'passed',
    evidence: '',
    stepsToReproduce: [],
  };

  try {
    await page.goto(url, { waitUntil: 'networkidle' });

    const inputField = await page.locator('input[type="search"], input[name="q"]');
    if (inputField.count() > 0) {
      const payload = "' UNION SELECT SLEEP(3)-- ";
      await inputField.fill(payload);
      await inputField.press('Enter');
      const body = await page.content();
      for (const keyword of sqliKeywords) {
        if (body.includes(keyword)) {
          result.status = 'failed';
          result.evidence = `Keyword '${keyword}' found in page response, indicating SQL injection possible via input parameter`;
          result.stepsToReproduce.push(`1. Navigate to ${url}`);
          result.stepsToReproduce.push(`2. Enter payload "' UNION SELECT SLEEP(3)-- " into search box`);
          result.stepsToReproduce.push(`3. Submit form — observe database error containing keyword '${keyword}'`);
          return result;
        }
      }
