export interface ScanResult {
  scanId: string;
  startTime: Date;
  endTime: Date;
  targetUrl: string;
  results: Array<{
    vulnType: string;
    severity: 'low' | 'medium' | 'high' | 'critical';
    description: string;
    status: 'passed' | 'failed';
    evidence: string;
    stepsToReproduce: string[];
    remediationAdvice: string[];
  }>;
  summary: {
    totalVulnerabilities: number;
    bySeverity: Array<{ severity: string; count: number }>;
  };
}

export function generateReport(scanResults: ScanResult[]): void {
  const reportPath = '/workspace/pentest/outputs/report.html';

  const summary = scanResults.reduce(
    (acc, res) => {
      for (const vuln of res.results) {
        if (!acc[vuln.severity]) { acc[vuln.severity] = 0; }
        acc[vuln.severity]++;
      }
      return acc;
    },
    { low: 0, medium: 0, high: 0, critical: 0 }
  );

  const html = `<html>
<head><title>OWASP TOP 10 Penetration Test Report</title><style>
body { font-family: sans-serif; padding: 20px; }
h1 { color: #333; }
table {
border-collapse: collapse; width: 100%; margin-top: 20px;
th, td { border: 1px solid #ddd; padding: 12px; }
th { background: #f5f5f5; }
.critical { color: #d32f2f; font-weight: bold; }
.high { color: #f57c00; }
.medium { color: #1976d2; }
.low { color: #4caf50; }
summary { cursor: pointer; user-select: none; }
</style></head>
<body>
<h1>OWASP TOP 10 Penetration Test Report</h1>
<p><i>Generated at ${new Date().toISOString()}</i></p>
<p>Summary — Critical: ${summary.critical}, High: ${summary.high}, Medium: ${summary.medium}, Low: ${summary.low}</p>
<table><tr><th>Scan ID</th><th>Target URL</th><th>Status</th></tr>
${scanResults.map((res) => `<tr>
<td>${res.scanId}</td>
<td>${res.targetUrl}</td>
<td>${resultsFailed(res.results) ? 'Failed' : 'Passed'}</td>
</tr>`).join('')}
</table>
</body>
</html>`;

  console.log(chalk.green('Report generated: /workspace/pentest/outputs/report.html'));

  process.exit(0);
}

function resultsFailed(results: Array<{ status: 'passed' | 'failed' }>): boolean {
  return results.some((r) => r.status === 'failed');
}

